import { describe, expect, test } from 'bun:test';
import * as fc from 'fast-check';

import { pendingItems } from '../src/pending/pending_model';

describe('testgen_pending__pendingItems', () => {
    const makePendingEdit = (id: string, state: unknown, comments: unknown[]): any => ({
      id,
      state,
      description: "A change",
      author: "author",
      nodeChanges: [],
      edgeChanges: [],
      groupChanges: [],
      annotationChanges: [],
      thread: { comments },
    });

    // WHEN: The stylesheet has an empty pendingEdits array; pendingItems returns an empty array.
    // THEN: It returns an empty array when stylesheet.pendingEdits is empty.
    test('empty_pending_edits', () => {
        const result = pendingItems({ pendingEdits: [] } as any);
        expect(result).toEqual([]);
    });

    test('ordered_pending_edits', () => {
        fc.assert(
            fc.property(fc.array(fc.string(), { minLength: 1 }), (value) => {
        const edits = value.map((id: string) => makePendingEdit(id, "PENDING", []));
        const result = pendingItems({ pendingEdits: edits } as any);
        expect(result).toHaveLength(value.length);
        expect(result.map((item) => item.id)).toEqual(value);
            })
        );
    });

    // WHEN: The stylesheet has a pendingEdits entry whose state is REJECTED; the entry is still included as a live proposal because membership in pendingEdits is the only inclusion signal.
    // THEN: It includes a REJECTED entry still present in pendingEdits as a live proposal.
    test('rejected_entry_retained', () => {
        const edit = makePendingEdit("rejected-edit", "REJECTED", []);
        const result = pendingItems({ pendingEdits: [edit] } as any);
        expect(result).toHaveLength(1);
        expect(result[0].id).toBe("rejected-edit");
    });

    test('state_does_not_filter', () => {
        fc.assert(
            fc.property(fc.array(fc.constantFrom("PENDING", "REJECTED", "APPLIED"), { minLength: 1 }), (value) => {
        const edits = value.map((state: string, index: number) => makePendingEdit(`edit-${index}`, state, []));
        const result = pendingItems({ pendingEdits: edits } as any);
        expect(result).toHaveLength(value.length);
        expect(result.map((item) => item.id)).toEqual(value.map((_: string, index: number) => `edit-${index}`));
            })
        );
    });

    test('stylesheet_thread_data', () => {
        fc.assert(
            fc.property(fc.array(fc.any()), (value) => {
        const edit = makePendingEdit("threaded-edit", "PENDING", value);
        const result = pendingItems({ pendingEdits: [edit] } as any);
        expect(result).toHaveLength(1);
        expect(result[0].comments).toBe(value);
            })
        );
    });

});

